function resultChips(p){const stats=Object.entries(p.statChanges||{}).filter(([,v])=>v!==0).map(([k,v])=>`<span>${statNames[k]} ${v>0?'+':''}${v}${k==='wealth'?'냥':''}</span>`);const relations=Object.entries(p.relationshipChanges||{}).filter(([,v])=>v!==0).map(([k,v])=>`<span>${relationNames[k]} ${v>0?'+':''}${v}</span>`);const trust=Object.entries(p.trustChanges||{}).filter(([,v])=>v!==0).map(([k,v])=>`<span>${relationNames[k]} 신뢰 ${v>0?'+':''}${v}</span>`);if(p.job&&p.job!=='없음')stats.push(`<span>새 직업 · ${esc(p.job)}</span>`);if(p.lifePath)stats.push(`<span>삶의 방향 · ${esc(p.lifePath)}</span>`);return [...stats,...relations,...trust].join('')}
