function syncCinematicTimeline(){if(cinematicTimer&&typeof clearTimeout==='function')clearTimeout(cinematicTimer);cinematicTimer=null;const r=run(),source=STORIES[r.storyId];if(screen!=='game'||r.pending||!source?.autoAdvanceDelays||typeof setTimeout!=='function')return;const entries=conversationEntries(source,null),cursor=Math.max(1,Math.min(r.dialogueCursor||1,entries.length));if(cursor>=entries.length)return;const sceneId=r.storyId,dialogueKey=r.dialogueSceneId,delay=source.autoAdvanceDelays[cursor-1]||850;cinematicTimer=setTimeout(()=>{if(screen!=='game'||run().storyId!==sceneId||run().dialogueSceneId!==dialogueKey)return;run().dialogueCursor=Math.min(entries.length,cursor+1);save();render()},delay)}
function finishOpeningTyping(){if(!typingLine)return false;clearTimeout(typingTimer);typingLine.element.textContent=typingLine.text;typingLine=null;document.querySelectorAll('.conversation-panel .choice,.conversation-panel .next').forEach(b=>b.disabled=false);return true}
function syncOpeningTyping(){if(typingTimer)clearTimeout(typingTimer);typingLine=null;if(screen!=='game'||run().storyId!=='house'||run().pending||modal)return;const entries=conversationEntries(STORIES.house,null),index=Math.min(run().dialogueCursor||1,entries.length)-1,element=document.querySelector('[data-dialogue-index="'+index+'"] p');if(!element)return;const text=entries[index].dialogue;typingLine={element,text};element.textContent='';document.querySelectorAll('.conversation-panel .choice,.conversation-panel .next').forEach(b=>b.disabled=true);let count=0;const tick=()=>{if(!typingLine||typingLine.element!==element)return;element.textContent=text.slice(0,++count);if(count>=text.length){finishOpeningTyping();return}typingTimer=setTimeout(tick,25)};tick()}
