document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b&&screen==='game'&&!modal&&e.target.closest('.conversation-game')){if(finishOpeningTyping())return;const source=STORIES[run().storyId],entries=conversationEntries(source,run().pending);if(run().storyId==='voice'||(run().storyId==='house'&&!run().pending&&(run().dialogueCursor||1)<entries.length))b={dataset:{action:(run().dialogueCursor||1)<entries.length?'advance-dialogue':'next'},disabled:false}}if(b&&['advance-dialogue','next'].includes(b.dataset.action)&&finishOpeningTyping())return;if(!b||b.disabled||!lockInput())return;if(b.dataset.historyCard){if(!meta().cards.includes(b.dataset.historyCard))return;selectedHistoryCardId=b.dataset.historyCard;return navigate('history')}if(b.dataset.concept){const ids=meta().conceptMistakes?.[b.dataset.concept]?.questionIds||[],id=ids.find(id=>!meta().reviewedQuestionIds.includes(id));if(id){reviewQuestionId=id;reviewAnswer=null;quizMode='review';return navigate('quiz')}return}if(b.dataset.chapterResult){e.stopPropagation?.();return showChapterResult(b.dataset.chapterResult)}if(b.dataset.nav)return navigate(b.dataset.nav);if(b.dataset.study){studyTab=b.dataset.study;return render()}if(b.dataset.choice!==undefined){applyChoice(state,run().storyId,Number(b.dataset.choice));const resultArt=ASSETS[run().pending?.resultIllustrationId];if(resultArt?.src)preloadImage(resultArt.src);save();return render()}if(b.dataset.answer!==undefined){const selected=Number(b.dataset.answer);if(quizMode==='story'){if(run().questionAnswer!==null)return;recordQuestion(state,run().activeQuestionId,selected)}else{if(reviewAnswer!==null)return;reviewAnswer=selected;const reviewChapter=QUESTIONS.find(q=>q.questionId===reviewQuestionId)?.chapterId;if(reviewChapter&&SPLIT_REVIEW_IDS[reviewChapter]){const right=recordCh01Review(reviewQuestionId,selected);if(quizMode==='ch01-practice'){meta().ch01ReviewSession.answers[reviewQuestionId]=selected;meta().ch01ReviewSession.results[reviewQuestionId]=right}}else{recordQuestion(state,reviewQuestionId,selected);run().questionAnswer=null}}save();return render()}if(b.dataset.review||b.dataset.practice){reviewQuestionId=b.dataset.review||b.dataset.practice;reviewAnswer=null;quizMode='review';return navigate('quiz')}switch(b.dataset.action){case'start-ch01-review':return startCh01Review(b.dataset.reviewChapter||'ch01');case'play':return play();case'current-main':return playMain();case'toggle-chapters':showAllChapters=!showAllChapters;return render();case'start-ch02':return startAvailableChapter('ch02');case'start-chapter':return startAvailableChapter(b.dataset.chapter);case'continue-chapter':{if(state.mainRun)restoreMainRun(state);modal=null;save();return play()}case'view-chapter-result':return showChapterResult(b.dataset.chapter);case'request-replay':modal={type:'replay-confirm',chapterId:b.dataset.chapter||resultChapterId||run().currentChapter};return render();case'confirm-replay':{const id=b.dataset.chapter;if(!beginReplay(state,id))return toast('완료한 챕터만 다시 플레이할 수 있습니다.');modal=null;resultChapterId=null;preloadChapterCore(id);save();screen='game';enterStory();render();window.scrollTo(0,0);return}case'view-replay-result':{const id=b.dataset.chapter||run().currentChapter;restoreMainRun(state);save();return showChapterResult(id)}case'return-replay-home':restoreMainRun(state);save();return navigate('home');case'restart-current':modal={type:'restart-current',chapterId:b.dataset.chapter||mainRun().currentChapter};return render();case'confirm-restart-current':if(state.mainRun)restoreMainRun(state);restartChapter(state);modal=null;resultChapterId=null;preloadChapterCore(run().currentChapter);save();return play();case'restart-episode':modal={type:'restart-episode'};return render();case'confirm-restart-episode':restartEpisodeMain(state);modal=null;resultChapterId=null;preloadChapterCore('ch01');save();return play();case'status':modal='status';return render();case'exam-image':{const q=QUESTIONS.find(q=>q.questionId===b.dataset.question);if(!q||!isVerifiedOfficialQuestion(q)||!q.sourceQuestionImage)return;modal={type:'exam-image',questionId:q.questionId,zoomed:false};return render()}case'exam-image-zoom':if(modal?.type==='exam-image'){modal.zoomed=!modal.zoomed;return render()}break;case'close':modal=null;return render();case'advance-dialogue':{const r=run(),source=r.pending?STORIES[r.pending.sourceSceneId]:STORIES[r.storyId],entries=conversationEntries(source,r.pending);r.dialogueCursor=Math.min(entries.length,(r.dialogueCursor||1)+1);if(!r.pending)applyDialogueMilestone(state,r.storyId,r.dialogueCursor);save();return render()}case'next':return nextStory();case'result-next':{const source=STORIES[run().pending?.sourceSceneId];run().pending=null;if(source?.afterChoiceQuestionSetId&&startQuestionSequence(source))return;enterStory();save();return render()}case'quiz-next':{if(quizMode==='ch01-practice')return continueCh01Review();if(quizMode==='review'){reviewQuestionId=null;reviewAnswer=null;studyTab='review';return navigate('study')}return continueStoryQuestion()}case'review-wrong':{const chapterId=resultChapterId||run().currentChapter,chapterIds=new Set(chapterQuestions(chapterId).map(q=>q.questionId)),resultData=resultChapterId?resultRun(chapterId):run(),first=meta().wrongQuestionIds.find(id=>chapterIds.has(id)&&resultData.questionResults[id]===false)||meta().wrongQuestionIds.find(id=>chapterIds.has(id))||meta().wrongQuestionIds[0];if(!first)return navigate('study');reviewQuestionId=first;reviewAnswer=null;quizMode='review';return navigate('quiz')}}if(b.dataset.chapter)return openChapterCard(b.dataset.chapter)});
